CREATE TABLE course (course_id BIGSERIAL PRIMARY KEY, title TEXT NOT NULL CHECK (btrim(title) <> ''), category VARCHAR(50) NOT NULL CHECK (btrim(category) <> ''), description TEXT NOT NULL DEFAULT '', course_order INT NOT NULL DEFAULT 0 CHECK (course_order >= 0), is_onboarding BOOLEAN NOT NULL DEFAULT FALSE, constellation_id BIGINT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), modified_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE lesson (lesson_id BIGSERIAL PRIMARY KEY, course_id BIGINT NOT NULL REFERENCES course(course_id) ON DELETE CASCADE, title TEXT NOT NULL CHECK (btrim(title) <> ''), description TEXT NOT NULL DEFAULT '', lesson_order INT NOT NULL CHECK (lesson_order >= 0), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), modified_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT uq_lesson_course_order UNIQUE(course_id, lesson_order));
CREATE INDEX ix_lesson_course_order ON lesson(course_id, lesson_order, lesson_id);
CREATE TABLE lesson_content (content_id BIGSERIAL PRIMARY KEY, lesson_id BIGINT NOT NULL REFERENCES lesson(lesson_id) ON DELETE CASCADE, content_order INT NOT NULL CHECK (content_order >= 0), content_type VARCHAR(10) NOT NULL CHECK (content_type IN ('TEXT','IMAGE','VIDEO','QUIZ')), body TEXT, media_url TEXT, quiz_id BIGINT REFERENCES quiz_item(quiz_id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), modified_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT ck_lesson_content_payload CHECK ((content_type='TEXT' AND body IS NOT NULL AND media_url IS NULL AND quiz_id IS NULL) OR (content_type IN ('IMAGE','VIDEO') AND body IS NULL AND media_url IS NOT NULL AND quiz_id IS NULL) OR (content_type='QUIZ' AND body IS NULL AND media_url IS NULL AND quiz_id IS NOT NULL)), CONSTRAINT uq_lesson_content_order UNIQUE(lesson_id,content_order), CONSTRAINT uq_lesson_content_quiz UNIQUE(quiz_id));
CREATE INDEX ix_lesson_content_lesson_order ON lesson_content(lesson_id, content_order, content_id);
